const viewBackgrounds = ['#eef2ff', '#f5f5f4', '#ecfeff']
const viewTransforms = [
  '',
  'translate(14 8) rotate(-8 200 140)',
  'translate(22 58) scale(0.92 0.72)',
]

export default function ShoeImage({ color, viewIndex, label }) {
  const transform = viewTransforms[viewIndex % viewTransforms.length]
  const bg = viewBackgrounds[viewIndex % viewBackgrounds.length]
  return (
    <svg viewBox="0 0 400 240" role="img" aria-label={label} className="shoe-svg">
      <rect width="400" height="240" rx="12" fill={bg} />
      <g transform={transform}>
        {/* upper */}
        <path
          d="M52 152 C56 108 84 74 132 62 C176 52 214 66 244 90 L330 122 C352 130 366 140 372 152 Z"
          fill={color.upper}
        />
        {/* heel counter */}
        <path d="M52 152 C54 118 66 92 94 76 L122 66 C110 96 106 124 108 152 Z" fill={color.shade} />
        {/* toe cap */}
        <path d="M330 122 C352 130 366 140 372 152 L318 152 C320 140 324 130 330 122 Z" fill={color.shade} />
        {/* laces */}
        <g stroke="#f8fafc" strokeWidth="6" strokeLinecap="round">
          <line x1="182" y1="82" x2="214" y2="94" />
          <line x1="198" y1="93" x2="230" y2="105" />
          <line x1="214" y1="104" x2="246" y2="116" />
        </g>
        {/* midsole */}
        <path d="M40 150 L350 150 C368 152 380 160 383 172 L385 182 L30 182 C32 168 34 158 40 150 Z" fill="#f8fafc" />
        {/* outsole */}
        <path
          d="M28 176 C20 186 24 202 44 206 L356 206 C378 205 388 194 384 180 L383 178 L31 178 Z"
          fill={color.sole}
        />
      </g>
    </svg>
  )
}

