import { useState } from 'react'
import ShoeImage from './ShoeImage.jsx'

export default function Gallery({ color, views, productName }) {
  const [index, setIndex] = useState(0)
  const total = views.length

  const goTo = (next) => setIndex(((next % total) + total) % total)

  const photoLabel = `${productName} in ${color.name}, ${views[index].label}`

  return (
    <section className="gallery" aria-roledescription="carousel" aria-label="Product photos">
      <div className="gallery-body">
        <ul className="thumbnails" aria-label="Choose photo">
          {views.map((view, i) => (
            <li key={view.id}>
              <button
                type="button"
                className={`thumbnail${i === index ? ' is-active' : ''}`}
                aria-current={i === index ? 'true' : undefined}
                aria-label={`Photo ${i + 1}: ${color.name}, ${view.label}`}
                onClick={() => setIndex(i)}
              >
                <ShoeImage color={color} viewIndex={i} label="" />
              </button>
            </li>
          ))}
        </ul>
        <div className="main-photo">
          <ShoeImage color={color} viewIndex={index} label={photoLabel} />
          <div className="gallery-controls">
            <button type="button" className="gallery-arrow" aria-label="Previous photo" onClick={() => goTo(index - 1)}>
              ‹
            </button>
            <span className="gallery-status" role="status">
              {index + 1} of {total}
            </span>
            <button type="button" className="gallery-arrow" aria-label="Next photo" onClick={() => goTo(index + 1)}>
              ›
            </button>
          </div>
        </div>
      </div>
    </section>
  )
}

