import { useEffect, useRef, useState } from 'react'

function suggestSize(cm, system) {
  if (system === 'US') {
    const us = Math.round((3 * (cm / 2.54) - 22) * 2) / 2
    return `US ${us}`
  }
  return `EU ${Math.round(1.5 * (cm + 1))}`
}

export default function SizeGuide({ open, onClose }) {
  const dialogRef = useRef(null)
  const closeRef = useRef(null)
  const [length, setLength] = useState('')
  const [system, setSystem] = useState('US')
  const [result, setResult] = useState(null)
  const [error, setError] = useState('')

  useEffect(() => {
    if (!open) return undefined
    const previouslyFocused = document.activeElement
    closeRef.current?.focus()

    function onKeyDown(event) {
      if (event.key === 'Escape') {
        onClose()
        return
      }
      if (event.key === 'Tab' && dialogRef.current) {
        const focusable = dialogRef.current.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
        )
        const first = focusable[0]
        const last = focusable[focusable.length - 1]
        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault()
          last.focus()
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault()
          first.focus()
        }
      }
    }

    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      previouslyFocused?.focus()
    }
  }, [open, onClose])

  if (!open) return null

  function findSize(event) {
    event.preventDefault()
    const cm = Number.parseFloat(length)
    if (Number.isNaN(cm) || cm < 20 || cm > 32) {
      setResult(null)
      setError('Enter a foot length between 20 and 32 cm.')
      return
    }
    setError('')
    setResult(suggestSize(cm, system))
  }

  return (
    <div className="modal-overlay">
      <div
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="size-guide-title"
        ref={dialogRef}
      >
        <div className="modal-header">
          <h2 id="size-guide-title">Size guide</h2>
          <button type="button" className="modal-close" onClick={onClose} ref={closeRef} aria-label="Close size guide">
            ✕
          </button>
        </div>
        <p>Measure your foot from heel to longest toe, then enter the length to find your size.</p>
        <form onSubmit={findSize}>
          <div className="field">
            <label htmlFor="foot-length">Foot length (cm)</label>
            <input
              id="foot-length"
              name="foot-length"
              type="number"
              inputMode="decimal"
              step="0.1"
              min="20"
              max="32"
              value={length}
              onChange={(e) => setLength(e.target.value)}
              required
            />
          </div>
          <fieldset className="field">
            <legend>Size system</legend>
            <label className="inline-option">
              <input
                type="radio"
                name="size-system"
                value="US"
                checked={system === 'US'}
                onChange={() => setSystem('US')}
              />
              US
            </label>
            <label className="inline-option">
              <input
                type="radio"
                name="size-system"
                value="EU"
                checked={system === 'EU'}
                onChange={() => setSystem('EU')}
              />
              EU
            </label>
          </fieldset>
          <button type="submit" className="button-primary">
            Find my size
          </button>
        </form>
        {error && (
          <p className="form-error" role="alert">
            {error}
          </p>
        )}
        {result && (
          <p className="size-result" role="status">
            Your recommended size: <strong>{result}</strong>
          </p>
        )}
      </div>
    </div>
  )
}

