import { useRef, useState } from 'react'

function Stars({ rating }) {
  const full = Math.round(rating)
  return (
    <span className="stars" role="img" aria-label={`${rating} out of 5 stars`}>
      {'★'.repeat(full)}
      {'☆'.repeat(5 - full)}
    </span>
  )
}

export default function InfoTabs({ product }) {
  const tabs = [
    {
      id: 'details',
      label: 'Details',
      content: (
        <ul>
          {product.details.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      ),
    },
    {
      id: 'reviews',
      label: 'Reviews',
      content: (
        <ul className="reviews">
          {product.reviews.map((review) => (
            <li key={review.author}>
              <Stars rating={review.rating} />
              <p>{review.text}</p>
              <p className="review-author">— {review.author}</p>
            </li>
          ))}
        </ul>
      ),
    },
    {
      id: 'shipping',
      label: 'Shipping',
      content: (
        <ul>
          {product.shipping.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      ),
    },
  ]

  const [active, setActive] = useState(0)
  const tabRefs = useRef([])

  function onKeyDown(event) {
    let next = null
    if (event.key === 'ArrowRight') next = (active + 1) % tabs.length
    if (event.key === 'ArrowLeft') next = (active - 1 + tabs.length) % tabs.length
    if (event.key === 'Home') next = 0
    if (event.key === 'End') next = tabs.length - 1
    if (next !== null) {
      event.preventDefault()
      setActive(next)
      tabRefs.current[next]?.focus()
    }
  }

  const activeTab = tabs[active]

  return (
    <section className="info-tabs" aria-label="More information">
      <div role="tablist" aria-label="Product information" onKeyDown={onKeyDown}>
        {tabs.map((tab, i) => (
          <button
            key={tab.id}
