                    value={quantity}
                    onChange={(e) => changeQuantity(e.target.value)}
                    onBlur={() => {
                      if (quantity === '') setQuantity(1)
                    }}
                  />
                  <button
                    type="button"
                    aria-label="Increase quantity"
                    onClick={() => changeQuantity((Number(quantity) || 1) + 1)}
                    disabled={Number(quantity) >= 10}
                  >
                    +
                  </button>
                </div>
              </div>

              <div className="actions">
                <button type="submit" className="button-primary add-to-cart">
                  Add to cart
                </button>
                <button
                  type="button"
                  className={`wishlist${wishlisted ? ' is-saved' : ''}`}
                  aria-pressed={wishlisted}
                  onClick={() => setWishlisted((saved) => !saved)}
                >
                  <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" fill={wishlisted ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2">
                    <path d="M12 21s-7.5-4.9-9.8-9.2C.6 8.6 2.3 5 5.7 5c2 0 3.4 1.1 4.3 2.4h4c.9-1.3 2.3-2.4 4.3-2.4 3.4 0 5.1 3.6 3.5 6.8C19.5 16.1 12 21 12 21z" />
                  </svg>
                  {wishlisted ? 'Saved to wishlist' : 'Save to wishlist'}
                </button>
              </div>

              <div
                className={`notice${notice ? ` notice-${notice.type}` : ''}`}
                role={notice?.type === 'error' ? 'alert' : 'status'}
                aria-live={notice?.type === 'error' ? 'assertive' : 'polite'}
              >
                {notice?.text}
              </div>
            </form>
          </div>
        </div>

        <InfoTabs product={product} />
        <Faq faqs={product.faqs} />
      </main>
      <Footer />
      <SizeGuide open={guideOpen} onClose={() => setGuideOpen(false)} />
    </>
  )
}

