import { useId, useRef, useState } from 'react'
import { product } from '../data/product.js'
import Header from '../components/Header.jsx'
import Gallery from '../components/Gallery.jsx'
import SizeGuide from '../components/SizeGuide.jsx'
import InfoTabs from '../components/InfoTabs.jsx'
import Faq from '../components/Faq.jsx'
import Footer from '../components/Footer.jsx'

export default function ProductPage() {
  const [cartCount, setCartCount] = useState(0)
  const [colorId, setColorId] = useState(product.colors[0].id)
  const [sizeId, setSizeId] = useState('')
  const [quantity, setQuantity] = useState(1)
  const [wishlisted, setWishlisted] = useState(false)
  const [guideOpen, setGuideOpen] = useState(false)
  const [notice, setNotice] = useState(null)
  const sizeSelectRef = useRef(null)
  const sizeIdBase = useId()

  const color = product.colors.find((c) => c.id === colorId)
  const size = product.sizes.find((s) => s.id === sizeId)

  function changeQuantity(next) {
    const value = Number.parseInt(next, 10)
    if (Number.isNaN(value)) {
      setQuantity('')
      return
    }
    setQuantity(Math.min(10, Math.max(1, value)))
  }

  function addToCart(event) {
    event.preventDefault()
    if (!size) {
      setNotice({ type: 'error', text: 'Please select a size before adding to your cart.' })
      sizeSelectRef.current?.focus()
      return
    }
    const qty = Number(quantity) || 1
    setCartCount((count) => count + qty)
    setNotice({
      type: 'success',
      text: `Added ${qty} × ${product.name} (${color.name}, ${size.label}) to your cart.`,
    })
  }

  return (
    <>
      <a href="#main-content" className="skip-link">
        Skip to main content
      </a>
      <Header cartCount={cartCount} />
      <main id="main-content" className="product-page">
        <nav aria-label="Breadcrumb" className="breadcrumbs">
          <ol>
            {product.breadcrumbs.map((crumb, i) => {
              const last = i === product.breadcrumbs.length - 1
              return (
                <li key={crumb.label}>
                  {last ? (
                    <span aria-current="page">{crumb.label}</span>
                  ) : (
                    <a href={crumb.href}>{crumb.label}</a>
                  )}
                </li>
              )
            })}
          </ol>
        </nav>

        <div className="product-layout">
          <Gallery key={color.id} color={color} views={product.views} productName={product.name} />

          <div className="product-info">
            <h1>{product.name}</h1>
            <p className="category">{product.category}</p>

            <p className="price">
              <span className="price-amount">${product.price.toFixed(2)}</span>
              <span className="price-info">
                <button type="button" className="info-button" aria-label="Price information" aria-describedby="price-tip">
                  i
                </button>
                <span role="tooltip" id="price-tip" className="tooltip">
                  Price includes taxes.
                </span>
              </span>
            </p>

            <form onSubmit={addToCart}>
              <fieldset className="colors">
                <legend>Color: {color.name}</legend>
                <div className="swatches" role="radiogroup" aria-label="Color">
                  {product.colors.map((c) => (
                    <label key={c.id} className={`swatch${c.id === colorId ? ' is-selected' : ''}`}>
                      <input
                        type="radio"
                        name="color"
                        value={c.id}
                        checked={c.id === colorId}
                        onChange={() => setColorId(c.id)}
                      />
                      <span className="swatch-dot" style={{ backgroundColor: c.swatch }} aria-hidden="true" />
                      <span className="visually-hidden">{c.name}</span>
                    </label>
                  ))}
                </div>
              </fieldset>

              <div className="size-row">
                <div className="field size-field">
                  <label htmlFor={`${sizeIdBase}-size`}>Size</label>
                  <select
                    id={`${sizeIdBase}-size`}
                    ref={sizeSelectRef}
                    value={sizeId}
                    onChange={(e) => setSizeId(e.target.value)}
                  >
                    <option value="">Select a size</option>
                    {product.sizes.map((s) => (
                      <option key={s.id} value={s.id} disabled={!s.inStock}>
                        {s.label}
                        {s.inStock ? '' : ' — sold out'}
                      </option>
                    ))}
                  </select>
                </div>
                <button type="button" className="link-button" onClick={() => setGuideOpen(true)}>
                  Size guide
                </button>
              </div>

              <div className="field quantity-field">
                <label htmlFor={`${sizeIdBase}-quantity`}>Quantity</label>
                <div className="quantity">
                  <button
                    type="button"
                    aria-label="Decrease quantity"
                    onClick={() => changeQuantity((Number(quantity) || 1) - 1)}
                    disabled={Number(quantity) <= 1}
                  >
                    −
                  </button>
                  <input
                    id={`${sizeIdBase}-quantity`}
                    type="number"
                    min="1"
                    max="10"
                    value={quantity}
                    onChange={(e) => changeQuantity(e.target.value)}
                    onBlur={() => {
                      if (quantity === '') setQuantity(1)
                    }}
                  />
                  <button
                    type="button"
                    aria-label="Increase quantity"
                    onClick={() => changeQuantity((Number(quantity) || 1) + 1)}
                    disabled={Number(quantity) >= 10}
                  >
                    +
                  </button>
                </div>
              </div>

              <div className="actions">
                <button type="submit" className="button-primary add-to-cart">
                  Add to cart
                </button>
                <button
                  type="button"
                  className={`wishlist${wishlisted ? ' is-saved' : ''}`}
                  aria-pressed={wishlisted}
                  onClick={() => setWishlisted((saved) => !saved)}
                >
                  <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" fill={wishlisted ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2">
                    <path d="M12 21s-7.5-4.9-9.8-9.2C.6 8.6 2.3 5 5.7 5c2 0 3.4 1.1 4.3 2.4h4c.9-1.3 2.3-2.4 4.3-2.4 3.4 0 5.1 3.6 3.5 6.8C19.5 16.1 12 21 12 21z" />
                  </svg>
                  {wishlisted ? 'Saved to wishlist' : 'Save to wishlist'}
                </button>
              </div>

              <div
                className={`notice${notice ? ` notice-${notice.type}` : ''}`}
                role={notice?.type === 'error' ? 'alert' : 'status'}
                aria-live={notice?.type === 'error' ? 'assertive' : 'polite'}
              >
                {notice?.text}
              </div>
            </form>
          </div>
        </div>

        <InfoTabs product={product} />
        <Faq faqs={product.faqs} />
      </main>
      <Footer />
      <SizeGuide open={guideOpen} onClose={() => setGuideOpen(false)} />
    </>
  )
}

args.streamContent:
:root {
  --accent: #f97316;
  --ink: #111827;
  --muted: #6b7280;
  --line: #e5e7eb;
  --error: #b91c1c;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: #fff;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -3rem;
  background: var(--ink);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 6px 6px;
  z-index: 30;
}

.skip-link:focus {
  top: 0;
}

/* Header */
.site-header {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.9rem 2rem;
  border-bottom: 1px solid var(--line);
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.main-nav {
  display: flex;
  gap: 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.main-nav a {
  color: var(--ink);
  text-decoration: none;
  font-weight: 600;
}

.main-nav a:hover {
  text-decoration: underline;
}

.cart-link {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--ink);
  text-decoration: none;
  font-weight: 700;
}

.cart-count {
  background: var(--ink);
  color: #fff;
  border-radius: 999px;
  min-width: 1.4rem;
  height: 1.4rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  padding: 0 0.3rem;
}

/* Page layout */
.product-page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 1rem 2rem 3rem;
}

.breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  list-style: none;
  margin: 0 0 1.5rem;
  padding: 0;
  font-size: 0.9rem;
  color: var(--muted);
}

.breadcrumbs li + li::before {
  content: '›';
  margin-right: 0.4rem;
  color: var(--muted);
}

.breadcrumbs a {
  color: var(--muted);
}

.breadcrumbs [aria-current] {
  color: var(--ink);
  font-weight: 600;
}

.product-layout {
  display: grid;
  grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  gap: 2.5rem;
  align-items: start;
}

@media (max-width: 800px) {
  .product-layout {
    grid-template-columns: 1fr;
  }
}

/* Gallery */
.gallery-body {
  display: flex;
  gap: 0.8rem;
}

.thumbnails {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.thumbnail {
  width: 72px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 10px;
  background: none;
  cursor: pointer;
}

.thumbnail.is-active {
  border-color: var(--accent);
}

.thumbnail:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.thumbnail .shoe-svg {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
}

.main-photo {
  flex: 1;
}

.main-photo .shoe-svg {
  width: 100%;
  height: auto;
  display: block;
}

.gallery-controls {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: 0.6rem;
}

.gallery-arrow {
  width: 2.4rem;
  height: 2.4rem;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: #fff;
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
}

.gallery-arrow:hover {
  background: #f3f4f6;
}

.gallery-status {
  font-size: 0.9rem;
  color: var(--muted);
}

/* Product info */
.product-info h1 {
  margin: 0;
  font-size: 1.8rem;
}

.category {
  margin: 0.2rem 0 1rem;
  color: var(--muted);
}

.price {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0 0 1.2rem;
}

.price-amount {
  font-size: 1.5rem;
  font-weight: 800;
}

.price-info {
  position: relative;
  display: inline-flex;
}

.info-button {
  width: 1.3rem;
  height: 1.3rem;
  border-radius: 50%;
  border: 1.5px solid var(--error);
  background: #fff;
  color: var(--error);
  font-size: 0.75rem;
  font-weight: 700;
  font-style: italic;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

.tooltip {
  display: none;
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  font-size: 0.8rem;
  padding: 0.4rem 0.7rem;
  border-radius: 6px;
  white-space: nowrap;
  z-index: 5;
}

.info-button:hover + .tooltip,
.info-button:focus-visible + .tooltip {
  display: block;
}

/* Colors */
.colors {
  border: 0;
  padding: 0;
  margin: 0 0 1.2rem;
}

.colors legend {
  font-weight: 600;
  padding: 0;
  margin-bottom: 0.5rem;
}

.swatches {
  display: flex;
  gap: 0.8rem;
}

.swatch {
  cursor: pointer;
}

.swatch input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.swatch-dot {
  display: block;
  width: 2rem;
  height: 2rem;
  border-radius: 50%;
  border: 2px solid #fff;
  box-shadow: 0 0 0 1px var(--line);
}

.swatch.is-selected .swatch-dot {
  box-shadow: 0 0 0 2px var(--accent);
}

.swatch input:focus-visible + .swatch-dot {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

/* Size & quantity */
.field {
  margin-bottom: 1.2rem;
  border: 0;
  padding: 0;
}

.field > label,
.field > legend {
  display: block;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.size-row {
  display: flex;
  align-items: flex-end;
  gap: 1rem;
}

.size-field {
  flex: 1;
}

select,
input[type='number'] {
  font: inherit;
  padding: 0.55rem 0.7rem;
  border: 1px solid #9ca3af;
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
}

select {
  width: 100%;
}

select:focus-visible,
input:focus-visible,
button:focus-visible,
a:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.link-button {
  background: none;
  border: 0;
  padding: 0 0 0.7rem;
  color: var(--ink);
  text-decoration: underline;
  cursor: pointer;
  font: inherit;
}

.quantity {
  display: inline-flex;
  align-items: stretch;
  border: 1px solid #9ca3af;
  border-radius: 8px;
  overflow: hidden;
}

.quantity button {
  width: 2.6rem;
  border: 0;
  background: #f3f4f6;
  font-size: 1.2rem;
  cursor: pointer;
}

.quantity button:disabled {
  color: #9ca3af;
  cursor: not-allowed;
}

.quantity input {
  width: 4rem;
  border: 0;
  border-left: 1px solid var(--line);
  border-right: 1px solid var(--line);
  border-radius: 0;
  text-align: center;
  appearance: textfield;
  -moz-appearance: textfield;
}

.quantity input::-webkit-outer-spin-button,
.quantity input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

/* Actions */
.actions {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}

.button-primary {
  background: var(--ink);
  color: #fff;
  border: 0;
  border-radius: 8px;
  padding: 0.8rem 1.6rem;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.button-primary:hover {
  background: #374151;
}

.add-to-cart {
  flex: 1;
  min-width: 10rem;
}

.wishlist {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: #fff;
  border: 1px solid #9ca3af;
  border-radius: 8px;
  padding: 0.8rem 1.1rem;
  font: inherit;
  cursor: pointer;
  color: var(--ink);
}

.wishlist.is-saved {
  color: var(--error);
  border-color: var(--error);
}

.notice {
  min-height: 1.5rem;
  margin-top: 1rem;
  font-weight: 600;
}

.notice:empty {
  margin-top: 0;
}

.notice-success {
  color: #15803d;
}

.notice-error {
  color: var(--error);
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(17, 24, 39, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  z-index: 20;
}

.modal {
  background: #fff;
  border-radius: 12px;
  padding: 1.5rem 2rem 2rem;
  max-width: 26rem;
  width: 100%;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

.modal-header h2 {
  margin: 0;
}

.modal-close {
  border: 0;
  background: none;
  font-size: 1.1rem;
  cursor: pointer;
  padding: 0.4rem;
}

.inline-option {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-right: 1.2rem;
  font-weight: 400;
}

.form-error {
  color: var(--error);
  font-weight: 600;
}

.size-result {
  background: #f0fdf4;
  border: 1px solid #86efac;
  border-radius: 8px;
  padding: 0.7rem 1rem;
}

/* Tabs */
.info-tabs {
  margin-top: 3rem;
}

[role='tablist'] {
  display: flex;
  gap: 0.5rem;
  border-bottom: 2px solid var(--line);
}

[role='tab'] {
  border: 0;
  background: none;
  font: inherit;
  font-weight: 600;
  padding: 0.7rem 1.2rem;
  cursor: pointer;
  color: var(--muted);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
}

[role='tab'][aria-selected='true'] {
  color: var(--ink);
  border-bottom-color: var(--accent);
}

.tab-panel {
  padding: 1.2rem 0.2rem;
  line-height: 1.6;
}

.reviews {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 1.2rem;
}

.stars {
  color: var(--accent);
  letter-spacing: 0.1em;
}

.review-author {
  color: var(--muted);
  margin: 0.2rem 0 0;
}

/* FAQ */
.faq {
  margin-top: 2.5rem;
}

.faq h2 {
  margin-bottom: 0.8rem;
}

.faq-item {
  border-bottom: 1px solid var(--line);
}

.faq-item h3 {
  margin: 0;
}

.faq-item button {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  background: none;
  border: 0;
  font: inherit;
  font-weight: 600;
  text-align: left;
  padding: 1rem 0.2rem;
  cursor: pointer;
}

.faq-icon {
  font-size: 1.2rem;
  width: 1.2rem;
  text-align: center;
}

.faq-item div[role='region'] {
  padding: 0 0.2rem 1.2rem 2.2rem;
  margin: 0;
  color: #374151;
}

.faq-item div[role='region'] p {
  margin: 0;
}

/* Footer */
.site-footer {
  background: var(--ink);
  color: #e5e7eb;
  padding: 2.5rem 2rem 2rem;
  margin-top: 3rem;
}

.footer-columns {
  max-width: 1120px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 2rem;
}

.site-footer h2 {
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #9ca3af;
  margin: 0 0 0.8rem;
}

.site-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.site-footer a {
  color: #e5e7eb;
  text-decoration: none;
}

.site-footer a:hover {
  text-decoration: underline;
}

.footer-note {
  max-width: 1120px;
  margin: 2.5rem auto 0;
  color: #9ca3af;
  font-size: 0.85rem;
}

