:root {
  --accent: #f97316;
  --ink: #111827;
  --muted: #6b7280;
  --line: #e5e7eb;
  --error: #b91c1c;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: #fff;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -3rem;
  background: var(--ink);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 6px 6px;
  z-index: 30;
}

.skip-link:focus {
  top: 0;
}

/* Header */
.site-header {
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 0.9rem 2rem;
  border-bottom: 1px solid var(--line);
}

.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.main-nav {
  display: flex;
  gap: 1.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.main-nav a {
  color: var(--ink);
  text-decoration: none;
  font-weight: 600;
}

.main-nav a:hover {
  text-decoration: underline;
}

.cart-link {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--ink);
  text-decoration: none;
  font-weight: 700;
}

.cart-count {
  background: var(--ink);
  color: #fff;
  border-radius: 999px;
  min-width: 1.4rem;
  height: 1.4rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  padding: 0 0.3rem;
}

/* Page layout */
.product-page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 1rem 2rem 3rem;
}

.breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  list-style: none;
  margin: 0 0 1.5rem;
  padding: 0;
  font-size: 0.9rem;
  color: var(--muted);
}

.breadcrumbs li + li::before {
  content: '›';
